'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const OUTPUT = 'trail-app.bundle.js';
const SOURCES = [
  'map-runtime.js',
  'map-style.js',
  'accessibility-runtime.js',
  'community-content-states.js',
  'offline-contributions.js',
  'icon-system.js',
  'guest-context.js',
  'auth-ui.js',
  'gpx-export.js',
  'offline-packages.js',
  'comparison-state.js',
  'breeds-data.js',
  'trust/evidence-v1.js',
  'scoring/recommendation-v1.js',
  'scoring/recommendation-adapters-v1.js',
  'scoring.js',
  'trail-trust.js',
  'trail-audits.js',
  'regions-config.js',
  'basemap-poi-click.js',
  'metrics.js',
  'metric-funnel.js',
  'hike-gps-policy.js',
  'route-rejoin.js',
  'hike-distance.js',
  'trail-routing-coverage.js',
  'trail-access-directions.js',
  'footpath-router.js',
  'pre-hike-readiness.js',
  'hike-session.js',
  'hike-completions.js',
  'post-hike-outcomes.js',
  'hike-mode.js',
  'detail-pois.js',
  'trail-photo-provenance.js',
  'trail-weather-window.js',
  'trail-reports.js',
  'veterinary-care.js',
  'trail-route-refs.js',
  'route-operational-facts.js',
  'trail.js',
  'trail-blueprint.js',
  'trail-detail-ui.js',
  'trail-mobile.js',
  'recommendation-decision.js',
  'recommendation-guides.js',
  'trail-recommendation.js',
];

function bundleSource(){
  const banner = '// Generated by scripts/build-trail-page-bundle.js. Do not edit directly.\n';
  return banner + SOURCES.map(file => {
    const source = fs.readFileSync(path.join(ROOT, file), 'utf8').trimEnd();
    return `\n// ---- ${file} ----\n${source}\n;`;
  }).join('\n') + '\n';
}

if(require.main === module){
  fs.writeFileSync(path.join(ROOT, OUTPUT), bundleSource());
  console.log(`Built ${OUTPUT} from ${SOURCES.length} ordered sources.`);
}

module.exports = { OUTPUT, SOURCES, bundleSource };
